LOG = logging.getLogger("nezzxbet")
DAY = 86_400_000
READ_PATHS = {"/api/config", "/api/me", "/api/rocket/state"}
_BUNDLE = None


def now_ms():
    return time.time_ns() // 1_000_000


def json_text(value):
    return json.dumps(value, ensure_ascii=False, separators=(",", ":"), allow_nan=False)


def sha256(value):
    return hashlib.sha256(str(value).encode()).hexdigest()


def uniform(seed, client_seed, nonce, context, cursor=0):
    text = f"{client_seed}:{nonce}:{context}:{cursor}"
    digest = hmac.new(seed.encode(), text.encode(), hashlib.sha256).hexdigest()
    return int(digest[:13], 16) / 2**52


def mine_positions(seed, client_seed, nonce, count):
    cells = list(range(25))
    for i in range(24, 0, -1):
        j = math.floor(uniform(seed, client_seed, nonce, "mines", 24-i) * (i+1))
        cells[i], cells[j] = cells[j], cells[i]
    return sorted(cells[:count])


def mines_multiplier(mines, opened, edge):
    if not opened:
        return 1.0
    probability = math.prod((25-mines-i)/(25-i) for i in range(opened))
    return (1-edge/10_000) / probability


def crash_point(value, edge, cap=1000):
    return min(cap, max(1.0, math.floor((1-edge/10_000)/(1-value)*100)/100))


def calibrate_drops(pets, price, edge):
    target = price*(1-edge/10_000)
    if not min(p["value"] for p in pets) < target < max(p["value"] for p in pets):
        raise ValueError("Case price cannot produce the configured RTP")

    def distribution(lam):
        raw = [-lam*p["value"]/price for p in pets]
        largest = max(raw)
        weights = [math.exp(v-largest) for v in raw]
        total = sum(weights)
        return [v/total for v in weights]

    lo, hi = -100.0, 100.0
    for _ in range(100):
        mid = (lo+hi)/2
        expected = sum(p["value"]*weight for p, weight in zip(pets, distribution(mid)))
        if expected > target:
            lo = mid
        else:
            hi = mid
    return [{"petId": p["id"], "chance": chance}
            for p, chance in zip(pets, distribution((lo+hi)/2))]


def pick_drop(drops, value):
    cumulative = 0.0
    for drop in drops:
        cumulative += drop["chance"]
        if value < cumulative:
            return drop["petId"]
    return drops[-1]["petId"]


class APIError(Exception):
    def __init__(self, message, status=400):
        super().__init__(message)
        self.status = status


def require(condition, message, status=400):
    if not condition:
        raise APIError(message, status)


def to_cents(value):
    try:
        require(not isinstance(value, bool), "Неверная сумма")
        number = decimal.Decimal(str(value))
        require(number.is_finite() and 0 <= number <= 1_000_000, "Неверная сумма")
        return int((number*100).quantize(decimal.Decimal(1), rounding=decimal.ROUND_HALF_UP))
    except (decimal.InvalidOperation, TypeError, ValueError, OverflowError):
        raise APIError("Неверная сумма") from None


def integer(value, message="Неверный ID"):
    try:
        require(not isinstance(value, bool), message)
        number = decimal.Decimal(str(value))
        require(number.is_finite() and number == number.to_integral_value()
                and abs(number) <= 2**53-1, message)
        return int(number)
    except (decimal.InvalidOperation, ValueError, TypeError):
        raise APIError(message) from None


def unique_ids(value, minimum=1, maximum=5):
    require(isinstance(value, list) and len(value) <= 100, "Неверный список предметов")
    require(all(isinstance(v, str) for v in value), "Неверный ID предмета")
    result = list(dict.fromkeys(value))
    require(minimum <= len(result) <= maximum, f"Выбери от {minimum} до {maximum} предметов")
    return result


def load_bundle():
    global _BUNDLE
    if _BUNDLE is None:
        _BUNDLE = json.loads(zlib.decompress(base64.b64decode(ASSET_BUNDLE)))
        for item in _BUNDLE["assets"].values():
            item["bytes"] = base64.b64decode(item.pop("base64"))
    return _BUNDLE


def load_dotenv(path):
    if not path.is_file():
        return
    for line in path.read_text(encoding="utf-8").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        key, sep, value = line.partition("=")
        if sep and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key.strip()):
            value = value.strip()
            if len(value) >= 2 and value[0] == value[-1] and value[0] in "\"'":
                value = value[1:-1]
            os.environ.setdefault(key.strip(), value)


@dataclasses.dataclass(frozen=True)
class Config:
    data_dir: Path
    admin_token: str
    port: int = 3000
    production: bool = False
    bot_token: str = ""
    admin_ids: frozenset = frozenset()
    site_url: str = ""
    bot_mode: str = "polling"
    webhook_secret: str = ""
    reset_webhook: bool = False
    require_telegram: bool = False
    edge: int = 600
    max_stake: int = 100_000
    max_payout: int = 5_000_000
    start_balance: int = 0
    daily_bonus: int = 500
    free_case_enabled: bool = True
    trade_receiver: str = "CANYAPON"
    support_url: str = "https://t.me/vibe_codernezzx"

    @classmethod
    def from_env(cls):
        base = Path(__file__).resolve().parent
        load_dotenv(base/".env")
        production = os.getenv("APP_ENV", os.getenv("NODE_ENV", "development")) == "production"
        token = os.getenv("ADMIN_TOKEN", "").strip()
        if not token:
            if production or os.getenv("RENDER"):
                raise ValueError("Set ADMIN_TOKEN to a random password of at least 24 characters")
            token = secrets.token_hex(24)
            LOG.warning("Local admin password for this run: %s", token)
        if len(token) < 24:
            raise ValueError("ADMIN_TOKEN must contain at least 24 characters")
        ids = os.getenv("ADMIN_IDS", os.getenv("ADMIN_ID", ""))
        admin_ids = frozenset(int(v) for v in re.split(r"[,;\s]+", ids.strip()) if v)
        if any(v <= 0 for v in admin_ids):
            raise ValueError("ADMIN_ID must be a positive numeric Telegram user ID")
        data_dir = Path(os.getenv("DATA_DIR", str(base/"data"))).resolve()
        if os.getenv("REQUIRE_PERSISTENCE", "false").lower() == "true" and data_dir == base/"data":
            raise ValueError("Set DATA_DIR to the persistent disk mount path")
        site_url = os.getenv("SITE_URL", os.getenv("WEBAPP_URL", os.getenv("RENDER_EXTERNAL_URL", ""))).strip().rstrip("/")
        if site_url:
            url = urllib.parse.urlsplit(site_url)
            if url.scheme not in {"http", "https"} or not url.netloc or url.path not in {"", "/"} or url.query or url.fragment or url.username:
                raise ValueError("SITE_URL must be the site origin, e.g. https://name.onrender.com")
        mode = os.getenv("BOT_MODE", "webhook" if site_url.startswith("https://") else "polling").lower()
        if mode not in {"webhook", "polling"}:
            raise ValueError("BOT_MODE must be webhook or polling")
        edge = integer(os.getenv("HOUSE_EDGE_BPS", "600"))
        if not 100 <= edge <= 2000:
            raise ValueError("HOUSE_EDGE_BPS must be between 100 and 2000")
        max_stake = to_cents(os.getenv("MAX_STAKE", "1000"))
        max_payout = to_cents(os.getenv("MAX_PAYOUT", "50000"))
        if max_stake < 100 or max_payout < max_stake:
            raise ValueError("MAX_PAYOUT must be >= MAX_STAKE, and MAX_STAKE must be >= 1")
        port = integer(os.getenv("PORT", "3000"))
        if not 0 <= port <= 65535:
            raise ValueError("PORT must be between 0 and 65535")
        bot_token = os.getenv("BOT_TOKEN", os.getenv("TELEGRAM_BOT_TOKEN", "")).strip()
        require_tg = os.getenv("REQUIRE_TELEGRAM", "false").lower() == "true"
        if require_tg and not bot_token:
            raise ValueError("REQUIRE_TELEGRAM requires BOT_TOKEN")
        secret = os.getenv("WEBHOOK_SECRET", "").strip()
        if secret and not re.fullmatch(r"[A-Za-z0-9_-]{24,256}", secret):
            raise ValueError("WEBHOOK_SECRET must have 24–256 URL-safe characters")
        return cls(data_dir, token, port, production, bot_token, admin_ids, site_url, mode,
                   secret, os.getenv("BOT_RESET_WEBHOOK", "false").lower() == "true",
                   require_tg, edge, max_stake, max_payout,
                   to_cents(os.getenv("START_BALANCE", "0")),
                   to_cents(os.getenv("DAILY_BONUS", "5")),
                   os.getenv("FREE_CASE_ENABLED", "true").lower() == "true",
                   os.getenv("TRADE_RECEIVER", "CANYAPON"),
                   os.getenv("SUPPORT_URL", "https://t.me/vibe_codernezzx"))


SCHEMA = """
PRAGMA journal_mode=WAL;
PRAGMA foreign_keys=ON;
PRAGMA busy_timeout=5000;
CREATE TABLE IF NOT EXISTS users(
 id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL,recovery_hash TEXT NOT NULL,
 telegram_id TEXT UNIQUE,balance INTEGER NOT NULL DEFAULT 0 CHECK(balance>=0),
 referral_balance INTEGER NOT NULL DEFAULT 0 CHECK(referral_balance>=0),referrer INTEGER,
 next_seed TEXT NOT NULL,nonce INTEGER NOT NULL DEFAULT 0,client_seed TEXT NOT NULL,
 daily_at INTEGER NOT NULL DEFAULT 0,free_at INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id INTEGER,
 admin INTEGER NOT NULL DEFAULT 0,expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS inventory(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),
 pet_id TEXT NOT NULL,locked INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS inventory_owner ON inventory(user_id,locked);
CREATE TABLE IF NOT EXISTS ledger(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id INTEGER NOT NULL REFERENCES users(id),
 delta INTEGER NOT NULL,balance_after INTEGER NOT NULL,reason TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS games(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),
 kind TEXT NOT NULL,status TEXT NOT NULL,stake INTEGER NOT NULL,payout INTEGER NOT NULL DEFAULT 0,
 state TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS game_owner ON games(user_id,kind,status);
CREATE TABLE IF NOT EXISTS requests(id TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),
 kind TEXT NOT NULL,status TEXT NOT NULL,amount INTEGER NOT NULL,items TEXT NOT NULL,
 roblox_name TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,reviewed_at INTEGER);
CREATE TABLE IF NOT EXISTS admin_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,action TEXT NOT NULL,
 target TEXT NOT NULL,details TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency(owner TEXT NOT NULL,key TEXT NOT NULL,fingerprint TEXT NOT NULL,
 response TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(owner,key));
CREATE TABLE IF NOT EXISTS bot_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS bot_chats(telegram_id TEXT PRIMARY KEY,chat_id INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_updates(update_id INTEGER PRIMARY KEY,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS telegram_outbox(id INTEGER PRIMARY KEY AUTOINCREMENT,dedupe TEXT UNIQUE,
 method TEXT NOT NULL,payload TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,
 retry_at INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
"""


class Store:
    def __init__(self, directory):
        directory.mkdir(parents=True, exist_ok=True)
        self.path = directory/"nezzxbet.sqlite"
        self.lock = threading.RLock()
        self.db = sqlite3.connect(self.path, timeout=5, isolation_level=None, check_same_thread=False)
        self.db.row_factory = sqlite3.Row
        self.db.executescript(SCHEMA)

    def q(self, sql, *params):
        row = self.db.execute(sql, params).fetchone()
        return dict(row) if row else None

    def all(self, sql, *params):
        return [dict(row) for row in self.db.execute(sql, params).fetchall()]

    def run(self, sql, *params):
        return self.db.execute(sql, params)

    @contextlib.contextmanager
    def transaction(self):
        with self.lock:
            self.db.execute("BEGIN IMMEDIATE")
            try:
                yield
                self.db.execute("COMMIT")
            except BaseException:
                self.db.execute("ROLLBACK")
                raise

    def balance(self, uid, amount, reason):
        if not isinstance(amount, int):
            raise ValueError("Balance amounts must be integer cents")
        result = self.run("UPDATE users SET balance=balance+? WHERE id=? AND balance+?>=0", amount, uid, amount)
        require(result.rowcount == 1, "Недостаточно монет")
        balance = self.q("SELECT balance FROM users WHERE id=?", uid)["balance"]
        self.run("INSERT INTO ledger(user_id,delta,balance_after,reason,created_at) VALUES(?,?,?,?,?)",
                 uid, amount, balance, reason, now_ms())

    def pet(self, uid, pet_id):
        item_id = str(uuid.uuid4())
        self.run("INSERT INTO inventory(id,user_id,pet_id,created_at) VALUES(?,?,?,?)", item_id, uid, pet_id, now_ms())
        return item_id

    def meta(self, key, default=None):
        row = self.q("SELECT value FROM bot_meta WHERE key=?", key)
        return row["value"] if row else default

    def set_meta(self, key, value):
        self.run("INSERT INTO bot_meta(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", key, str(value))

    def backup(self, path):
        path = Path(path).resolve()
        require(path != self.path.resolve(), "Выбери отдельный файл для копии")
        path.parent.mkdir(parents=True, exist_ok=True)
        with self.lock, sqlite3.connect(path) as target:
            self.db.backup(target)
        return path

    def close(self):
        with self.lock:
            self.db.close()


class Application:
    def __init__(self, config):
        self.cfg = config
        self.store = Store(config.data_dir)
        self.q, self.all, self.run = self.store.q, self.store.all, self.store.run
        catalog = load_bundle()["catalog"]
        self.pets = copy.deepcopy(catalog["pets"])
        self.pet_by_id = {p["id"]: p for p in self.pets}
        self.cases = []
        for definition in catalog["cases"]:
            case = {k: v for k, v in definition.items() if k != "petIds"}
            case["drops"] = calibrate_drops([self.pet_by_id[p] for p in definition["petIds"]], case["price"], config.edge)
            case["rtp"] = sum(self.pet_by_id[d["petId"]]["value"]*d["chance"] for d in case["drops"])/case["price"]
            self.cases.append(case)
        self.case_by_id = {c["id"]: c for c in self.cases}
        self.rate_lock, self.rates = threading.Lock(), {}
        self.stop_event = threading.Event()
        with self.store.transaction():
            secret = config.webhook_secret or self.store.meta("webhook_secret") or secrets.token_urlsafe(32)
            self.store.set_meta("webhook_secret", secret)
        self.webhook_secret = secret

    def rate_limit(self, key, auth=False):
        with self.rate_lock:
            current = time.monotonic()
            key = (key, auth)
            at, count = self.rates.get(key, (current, 0))
            if current-at >= 60:
                at, count = current, 0
            count += 1
            self.rates[key] = (at, count)
            require(count <= (20 if auth else 400), "Слишком много запросов. Подожди минуту.", 429)

    def session(self, headers, admin=False):
        cookies = http.cookies.SimpleCookie()
        try:
            cookies.load(headers.get("Cookie", ""))
        except http.cookies.CookieError:
            return None
        value = cookies.get("nezzx_admin" if admin else "nezzx_session")
        if not value:
            return None
        return self.q("SELECT * FROM sessions WHERE token_hash=? AND expires>? AND admin=?",
                      sha256(value.value), now_ms(), int(admin))

    def issue_session(self, uid, admin=False):
        token = secrets.token_hex(32)
        days = 1 if admin else 30
        self.run("INSERT INTO sessions(token_hash,user_id,admin,expires) VALUES(?,?,?,?)",
                 sha256(token), uid, int(admin), now_ms()+days*DAY)
        name = "nezzx_admin" if admin else "nezzx_session"
        return f"{name}={token}; Path=/; HttpOnly; SameSite=Lax; Max-Age={days*86400}" + ("; Secure" if self.cfg.production else "")

    def user(self, headers):
        session = self.session(headers)
        require(session, "Нужно войти в аккаунт", 401)
        user = self.q("SELECT * FROM users WHERE id=?", session["user_id"])
        require(user, "Аккаунт не найден", 401)
        return user

    def create_user(self, name, telegram_id=None, referrer=None):
        try:
            ref = integer(referrer)
        except APIError:
            ref = None
        if ref is not None and not self.q("SELECT id FROM users WHERE id=?", ref):
            ref = None
        code = secrets.token_hex(18)
        result = self.run("INSERT INTO users(name,recovery_hash,telegram_id,referrer,next_seed,client_seed,created_at) VALUES(?,?,?,?,?,?,?)",
                          str(name or "Игрок")[:40], sha256(code), telegram_id, ref, secrets.token_hex(32), secrets.token_hex(8), now_ms())
        uid = result.lastrowid
        if self.cfg.start_balance:
            self.store.balance(uid, self.cfg.start_balance, "Стартовый баланс")
        return self.q("SELECT * FROM users WHERE id=?", uid), code

    def seed_for(self, user, context):
        seed = {"serverSeed": user["next_seed"], "serverSeedHash": sha256(user["next_seed"]),
                "clientSeed": user["client_seed"], "nonce": user["nonce"], "context": context}
        self.run("UPDATE users SET next_seed=?,nonce=nonce+1 WHERE id=?", secrets.token_hex(32), user["id"])
        return seed

    @staticmethod
    def roll(seed):
        return uniform(seed["serverSeed"], seed["clientSeed"], seed["nonce"], seed["context"])

    def insert_game(self, user, kind, stake, payout, state, status="finished"):
        game_id = str(uuid.uuid4())
        self.run("INSERT INTO games(id,user_id,kind,status,stake,payout,state,created_at) VALUES(?,?,?,?,?,?,?,?)",
                 game_id, user["id"], kind, status, stake, payout, json_text(state), now_ms())
        return game_id

    def save_game(self, game, status, payout=0):
        self.run("UPDATE games SET state=?,status=?,payout=? WHERE id=?", json_text(game["state"]), status, payout, game["id"])
        game["status"], game["payout"] = status, payout

    @staticmethod
    def decode_game(game):
        if game:
            game["state"] = json.loads(game["state"])
        return game

    def active_game(self, user, kind):
        return self.decode_game(self.q("SELECT * FROM games WHERE user_id=? AND kind=? AND status='active'", user["id"], kind))

    def charge_stake(self, user, body):
        if body.get("inventoryIds"):
            ids = unique_ids(body["inventoryIds"])
            owned = [self.q("SELECT * FROM inventory WHERE id=? AND user_id=? AND locked=0", i, user["id"]) for i in ids]
            require(all(owned), "Один из питомцев недоступен")
            amount = sum(self.pet_by_id[i["pet_id"]]["value"] for i in owned)
            require(amount <= self.cfg.max_stake, "Ставка выше лимита")
            for item in owned:
                self.run("DELETE FROM inventory WHERE id=?", item["id"])
            return amount
        amount = to_cents(body.get("amount"))
        require(100 <= amount <= self.cfg.max_stake, "Ставка от 1 монеты до лимита")
        self.store.balance(user["id"], -amount, "Ставка")
        return amount

    def award(self, user, amount, as_pet=False, cap=None):
        amount = min(math.floor(amount), self.cfg.max_payout if cap is None else cap)
        item, remainder = None, amount
        if as_pet and self.q("SELECT COUNT(*) AS n FROM inventory WHERE user_id=?", user["id"])["n"] < 1000:
            available = [p for p in self.pets if p["value"] <= amount]
            if available:
                pet = max(available, key=lambda p: p["value"])
                item = {**pet, "inventoryId": self.store.pet(user["id"], pet["id"])}
                remainder -= pet["value"]
        if remainder:
            self.store.balance(user["id"], remainder, "Выигрыш")
        return {"payout": amount, "item": item, "coins": remainder}

    @staticmethod
    def rocket_multiplier(state):
        seconds = max(0, now_ms()-state["startAt"])
        return math.exp(min(seconds*.00008, math.log(1001)))

    def settle_rocket(self, user, game):
        if not game or now_ms() < game["state"]["startAt"]:
            return game
        state = game["state"]
        current = self.rocket_multiplier(state)
        limit = min(state["auto"] or math.inf, state["maxPayout"]/game["stake"])
        if limit < state["crash"] and current >= limit:
            reward = self.award(user, game["stake"]*limit, state["asPet"], state["maxPayout"])
            state.update(reward=reward, finalMultiplier=limit)
            self.save_game(game, "won", reward["payout"])
        elif current >= state["crash"]:
            state["finalMultiplier"] = state["crash"]
            self.save_game(game, "lost")
        return game

    def public_game(self, game):
        if not game:
            return None
        state = game["state"]
        result = {"id": game["id"], "kind": game["kind"], "status": game["status"], "stake": game["stake"],
                  "payout": game["payout"], "createdAt": game["created_at"], "commit": state["seed"]["serverSeedHash"]}
        if game["kind"] == "mines":
            result.update(mines=state["mines"], opened=state["opened"], edge=state["edge"],
                          multiplier=mines_multiplier(state["mines"], len(state["opened"]), state["edge"]), maxPayout=state["maxPayout"])
        elif game["kind"] == "rocket":
            result.update(startAt=state["startAt"], auto=state["auto"],
                          multiplier=self.rocket_multiplier(state) if game["status"] == "active" else state.get("finalMultiplier", 1))
        if game["status"] != "active":
            result.update(state)
            result["proof"] = state["seed"]
        return result

    def profile(self, user):
        self.settle_rocket(user, self.active_game(user, "rocket"))
        user = self.q("SELECT * FROM users WHERE id=?", user["id"])
        uid = user["id"]
        inventory = [{**self.pet_by_id[i["pet_id"]], "inventoryId": i["id"], "locked": bool(i["locked"])}
                     for i in self.all("SELECT * FROM inventory WHERE user_id=? ORDER BY created_at DESC LIMIT 1000", uid)]
        requests = self.all("SELECT * FROM requests WHERE user_id=? ORDER BY created_at DESC LIMIT 30", uid)
        for request in requests:
            request["items"] = json.loads(request["items"])
        return {"id": uid, "name": user["name"], "balance": user["balance"], "referralBalance": user["referral_balance"],
                "telegram": bool(user["telegram_id"]), "inventory": inventory, "clientSeed": user["client_seed"],
                "stats": self.q("SELECT COUNT(*) AS rounds,COALESCE(SUM(stake),0) AS spent,COALESCE(SUM(payout),0) AS won FROM games WHERE user_id=? AND status!='active'", uid),
                "fairness": {"nextCommit": sha256(user["next_seed"]), "nonce": user["nonce"]},
                "dailyAt": user["daily_at"], "freeAt": user["free_at"],
                "referralCount": self.q("SELECT COUNT(*) AS n FROM users WHERE referrer=?", uid)["n"],
                "mines": self.public_game(self.active_game(user, "mines")),
                "rocket": self.public_game(self.active_game(user, "rocket")), "requests": requests,
                "ledger": self.all("SELECT * FROM ledger WHERE user_id=? ORDER BY id DESC LIMIT 40", uid),
                "history": [self.public_game(self.decode_game(g)) for g in self.all("SELECT * FROM games WHERE user_id=? AND status!='active' ORDER BY created_at DESC LIMIT 30", uid)]}

    def verify_telegram(self, data):
        require(self.cfg.bot_token, "Telegram-вход ещё не настроен")
        require(isinstance(data, str) and len(data) <= 16000, "Неверные данные Telegram", 401)
        pairs = urllib.parse.parse_qsl(data, keep_blank_values=True)
        require(len(dict(pairs)) == len(pairs), "Повторяющиеся поля Telegram", 401)
        fields = dict(pairs)
        given = fields.pop("hash", "")
        secret = hmac.new(b"WebAppData", self.cfg.bot_token.encode(), hashlib.sha256).digest()
        check = "\n".join(f"{key}={value}" for key, value in sorted(fields.items()))
        expected = hmac.new(secret, check.encode(), hashlib.sha256).hexdigest()
        require(hmac.compare_digest(given, expected), "Неверная подпись Telegram", 401)
        age = now_ms()/1000-integer(fields.get("auth_date"), "Неверная дата Telegram")
        require(-60 <= age < 3600, "Сессия Telegram устарела", 401)
        try:
            user = json.loads(fields.get("user", "null"))
        except json.JSONDecodeError:
            user = None
        require(isinstance(user, dict) and isinstance(user.get("id"), int) and user["id"] > 0, "Нет пользователя Telegram", 401)
        return user

    def queue(self, method, payload, dedupe=None):
        self.run("INSERT OR IGNORE INTO telegram_outbox(dedupe,method,payload,created_at) VALUES(?,?,?,?)",
                 dedupe, method, json_text(payload), now_ms())

    def notify_user(self, uid, text, dedupe):
        if not self.cfg.bot_token:
            return
        row = self.q("SELECT c.chat_id FROM users u JOIN bot_chats c ON c.telegram_id=u.telegram_id WHERE u.id=?", uid)
        if row:
            self.queue("sendMessage", {"chat_id": row["chat_id"], "text": text, "parse_mode": "HTML"}, dedupe)

    def notify_request(self, request):
        if not self.cfg.bot_token:
            return
        label = "Депозит" if request["kind"] == "deposit" else "Вывод"
        text = (f"<b>{label}: {request['id'][:8]}</b>\nИгрок #{request['user_id']}\n"
                f"Roblox: <code>{html.escape(request['roblox_name'])}</code>\n"
                f"Стоимость: {request['amount']/100:g} монет\n"
                + ", ".join(html.escape(self.pet_by_id[i["petId"]]["name"]) for i in request["items"]))
        for admin_id in self.cfg.admin_ids:
            self.queue("sendMessage", {"chat_id": admin_id, "text": text, "parse_mode": "HTML",
                       "reply_markup": {"inline_keyboard": [[{"text": "Проверить заявку", "callback_data": f"request:{request['id']}"}]]}},
                       f"request:{request['id']}:{admin_id}")

    def daily(self, user):
        require(now_ms()-user["daily_at"] >= DAY, "Бонус доступен раз в 24 часа")
        require(self.cfg.daily_bonus > 0, "Бонус отключён")
        self.run("UPDATE users SET daily_at=? WHERE id=?", now_ms(), user["id"])
        self.store.balance(user["id"], self.cfg.daily_bonus, "Ежедневный бонус")
        return {"amount": self.cfg.daily_bonus}

    def admin_credit(self, body, actor="web"):
        uid = integer(body.get("userId"))
        amount = to_cents(body.get("amount"))
        require(amount > 0, "Сумма должна быть положительной")
        require(self.q("SELECT id FROM users WHERE id=?", uid), "Игрок не найден")
        note = str(body.get("note") or "Ручное начисление")[:200]
        self.store.balance(uid, amount, f"Администратор: {note}")
        self.run("INSERT INTO admin_audit(action,target,details,created_at) VALUES(?,?,?,?)",
                 "credit", str(uid), json_text({"amount": amount, "note": note, "actor": actor}), now_ms())
        self.notify_user(uid, f"На баланс начислено <b>{amount/100:g} монет</b>.\n{html.escape(note)}", f"credit:{uuid.uuid4()}")
        return {"ok": True}

    def admin_review(self, body, actor="web"):
        request = self.q("SELECT * FROM requests WHERE id=? AND status='pending'", str(body.get("id", "")))
        require(request, "Заявка уже обработана")
        decision = body.get("decision")
        require(decision in {"approved", "rejected"}, "Неверное решение")
        items = json.loads(request["items"])
        if request["kind"] == "deposit" and decision == "approved":
            self.store.balance(request["user_id"], request["amount"], f"Трейд принят: {request['id'][:8]}")
            user = self.q("SELECT referrer FROM users WHERE id=?", request["user_id"])
            if user["referrer"]:
                self.run("UPDATE users SET referral_balance=referral_balance+? WHERE id=?", request["amount"]*3//100, user["referrer"])
        if request["kind"] == "withdraw":
            for item in items:
                if decision == "approved":
                    self.run("DELETE FROM inventory WHERE id=? AND user_id=?", item["inventoryId"], request["user_id"])
                else:
                    self.run("UPDATE inventory SET locked=0 WHERE id=?", item["inventoryId"])
        note = str(body.get("note") or "")[:200]
        self.run("UPDATE requests SET status=?,note=?,reviewed_at=? WHERE id=?", decision, note, now_ms(), request["id"])
        self.run("INSERT INTO admin_audit(action,target,details,created_at) VALUES(?,?,?,?)", "review", request["id"],
                 json_text({"decision": decision, "kind": request["kind"], "amount": request["amount"], "actor": actor}), now_ms())
        status = "подтверждена" if decision == "approved" else "отклонена"
        self.notify_user(request["user_id"], f"Заявка <code>{request['id'][:8]}</code> {status}.\n{html.escape(note)}", f"review:{request['id']}")
        return {"ok": True}

    def admin_data(self, body):
        search = str(body.get("search", ""))[:60]
        requests = self.all("SELECT r.*,u.name FROM requests r JOIN users u ON u.id=r.user_id ORDER BY CASE WHEN r.status='pending' THEN 0 ELSE 1 END,r.created_at DESC LIMIT 100")
        for request in requests:
            request["items"] = json.loads(request["items"])
        return {"users": self.all("SELECT id,name,balance,telegram_id,created_at FROM users WHERE CAST(id AS TEXT) LIKE ? OR name LIKE ? ORDER BY id DESC LIMIT 100", f"%{search}%", f"%{search}%"),
                "requests": requests, "audit": self.all("SELECT * FROM admin_audit ORDER BY id DESC LIMIT 50"),
                "stats": {"users": self.q("SELECT COUNT(*) AS n FROM users")["n"],
                          "balance": self.q("SELECT COALESCE(SUM(balance),0) AS n FROM users")["n"],
                          "pending": self.q("SELECT COUNT(*) AS n FROM requests WHERE status='pending'")["n"],
                          "gameMargin": self.q("SELECT COALESCE(SUM(stake-payout),0) AS n FROM games WHERE status!='active'")["n"]}}

    def route(self, path, body, headers):
        cookie = None
        if path == "/api/config":
            return {"name": "nezzxBET", "pets": self.pets, "cases": self.cases, "edgeBps": self.cfg.edge,
                    "maxStake": self.cfg.max_stake, "maxPayout": self.cfg.max_payout, "dailyBonus": self.cfg.daily_bonus,
                    "freeCaseEnabled": self.cfg.free_case_enabled, "telegramEnabled": bool(self.cfg.bot_token),
                    "botUsername": self.store.meta("bot_username", ""), "requireTelegram": self.cfg.require_telegram,
                    "tradeReceiver": self.cfg.trade_receiver, "supportUrl": self.cfg.support_url, "serverTime": now_ms()}, cookie
        if path == "/api/auth/guest":
            require(not self.cfg.require_telegram, "Войди через Telegram")
            session = self.session(headers)
            if session:
                return {"user": self.profile(self.q("SELECT * FROM users WHERE id=?", session["user_id"]))}, cookie
            user, code = self.create_user(body.get("name"), referrer=body.get("referrer"))
            return {"user": self.profile(user), "recoveryCode": code}, self.issue_session(user["id"])
        if path == "/api/auth/restore":
            user = self.q("SELECT * FROM users WHERE id=?", integer(body.get("id")))
            require(user and hmac.compare_digest(sha256(body.get("recoveryCode", "")), user["recovery_hash"]), "ID или код восстановления неверны", 401)
            return {"user": self.profile(user)}, self.issue_session(user["id"])
        if path == "/api/auth/telegram":
            telegram = self.verify_telegram(body.get("initData"))
            user = self.q("SELECT * FROM users WHERE telegram_id=?", str(telegram["id"]))
            code = None
            if not user:
                user, code = self.create_user(telegram.get("first_name"), str(telegram["id"]), body.get("referrer"))
            return {"user": self.profile(user), "recoveryCode": code}, self.issue_session(user["id"])
        if path == "/api/admin/login":
            require(hmac.compare_digest(sha256(body.get("token", "")), sha256(self.cfg.admin_token)), "Неверный пароль", 401)
            return {"ok": True}, self.issue_session(None, True)
        if path.startswith("/api/admin/"):
            session = self.session(headers, True)
            require(session, "Нужен вход в админку", 401)
            if path == "/api/admin/data":
                return self.admin_data(body), cookie
            if path == "/api/admin/credit":
                return self.admin_credit(body), cookie
            if path == "/api/admin/review":
                return self.admin_review(body), cookie
            if path == "/api/admin/logout":
                self.run("DELETE FROM sessions WHERE token_hash=?", session["token_hash"])
                return {"ok": True}, cookie
            raise APIError("Метод не найден", 404)
        user = self.user(headers)
        uid = user["id"]
        if path == "/api/me":
            return {"user": self.profile(user), "serverTime": now_ms()}, cookie
        if path == "/api/profile":
            name = str(body.get("name", "")).strip()
            require(2 <= len(name) <= 40, "Имя от 2 до 40 символов")
            self.run("UPDATE users SET name=? WHERE id=?", name, uid)
            return {"ok": True}, cookie
        if path == "/api/client-seed":
            require(not self.active_game(user, "mines") and not self.active_game(user, "rocket"), "Сначала заверши активную игру")
            seed = str(body.get("seed", "")).strip()
            require(3 <= len(seed) <= 64, "Seed от 3 до 64 символов")
            self.run("UPDATE users SET client_seed=? WHERE id=?", seed, uid)
            return {"ok": True}, cookie
        if path == "/api/bonus/daily":
            return self.daily(user), cookie
        if path == "/api/referral/transfer":
            require(user["referral_balance"] > 0, "Нет монет для перевода")
            self.run("UPDATE users SET referral_balance=0 WHERE id=?", uid)
            self.store.balance(uid, user["referral_balance"], "Реферальное начисление")
            return {"amount": user["referral_balance"]}, cookie
        if path == "/api/shop/buy":
            pet = self.pet_by_id.get(str(body.get("petId", "")))
            require(pet, "Питомец не найден")
            require(self.q("SELECT COUNT(*) AS n FROM inventory WHERE user_id=?", uid)["n"] < 1000, "Инвентарь заполнен")
            self.store.balance(uid, -pet["value"], f"Покупка: {pet['name']}")
            return {"item": {**pet, "inventoryId": self.store.pet(uid, pet["id"])}}, cookie
        if path == "/api/inventory/sell":
            item = self.q("SELECT * FROM inventory WHERE id=? AND user_id=? AND locked=0", str(body.get("inventoryId", "")), uid)
            require(item, "Питомец недоступен")
            self.run("DELETE FROM inventory WHERE id=?", item["id"])
            self.store.balance(uid, self.pet_by_id[item["pet_id"]]["value"], "Продажа питомца")
            return {"ok": True}, cookie
        if path == "/api/cases/open":
            case = self.case_by_id.get(str(body.get("caseId", "")))
            require(case, "Кейс не найден")
            require(self.q("SELECT COUNT(*) AS n FROM inventory WHERE user_id=?", uid)["n"] < 1000, "Инвентарь заполнен")
            free = body.get("free") is True
            if free:
                require(self.cfg.free_case_enabled, "Бесплатные кейсы отключены")
                require(case["id"] == "blocks" and now_ms()-user["free_at"] >= DAY//2, "Бесплатный кейс доступен раз в 12 часов")
                self.run("UPDATE users SET free_at=? WHERE id=?", now_ms(), uid)
            else:
                self.store.balance(uid, -case["price"], f"Кейс: {case['name']}")
            seed = self.seed_for(user, f"case:{case['id']}")
            value = self.roll(seed)
            pet = self.pet_by_id[pick_drop(case["drops"], value)]
            state = {"seed": seed, "roll": value, "caseId": case["id"], "item": {**pet, "inventoryId": self.store.pet(uid, pet["id"])}, "odds": case["drops"], "edgeBps": self.cfg.edge}
            game_id = self.insert_game(user, "case", 0 if free else case["price"], pet["value"], state)
            return {"id": game_id, **state, "proof": seed}, cookie
        if path == "/api/upgrade":
            target = self.pet_by_id.get(str(body.get("targetId", "")))
            require(target, "Выбери цель")
            stake = self.charge_stake(user, body)
            require(target["value"] > stake, "Цель должна стоить дороже ставки")
            require(target["value"] <= self.cfg.max_payout, "Цель выше лимита выигрыша")
            require(self.q("SELECT COUNT(*) AS n FROM inventory WHERE user_id=?", uid)["n"] < 1000, "Инвентарь заполнен")
            chance = stake/target["value"]*(1-self.cfg.edge/10_000)
            seed = self.seed_for(user, "upgrade")
            value, won = self.roll(seed), False
            won = value < chance
            item = {**target, "inventoryId": self.store.pet(uid, target["id"])} if won else None
            state = {"seed": seed, "chance": chance, "roll": value, "won": won, "item": item, "targetId": target["id"]}
            game_id = self.insert_game(user, "upgrade", stake, target["value"] if won else 0, state, "won" if won else "lost")
            return {"id": game_id, **state, "proof": seed}, cookie
        if path == "/api/mines/start":
            require(not self.active_game(user, "mines"), "Сначала заверши текущее поле")
            mines = integer(body.get("mines"), "Неверное число мин")
            require(1 <= mines <= 24, "Мин должно быть от 1 до 24")
            stake = self.charge_stake(user, body)
            seed = self.seed_for(user, "mines")
            state = {"seed": seed, "mines": mines, "bombs": mine_positions(seed["serverSeed"], seed["clientSeed"], seed["nonce"], mines),
                     "opened": [], "edge": self.cfg.edge, "maxPayout": self.cfg.max_payout, "asPet": body.get("asPet") is True}
            game_id = self.insert_game(user, "mines", stake, 0, state, "active")
            return self.public_game(self.decode_game(self.q("SELECT * FROM games WHERE id=?", game_id))), cookie
        if path in {"/api/mines/reveal", "/api/mines/cashout"}:
            game = self.active_game(user, "mines")
            require(game, "Нет активной игры")
            state = game["state"]
            if path.endswith("reveal"):
                index = integer(body.get("index"), "Неверная клетка")
                require(0 <= index < 25, "Неверная клетка")
                require(index not in state["opened"], "Клетка уже открыта")
                if index in state["bombs"]:
                    self.save_game(game, "lost")
                    return self.public_game(game), cookie
                state["opened"].append(index)
            else:
                require(state["opened"], "Открой хотя бы одну клетку")
            amount = math.floor(game["stake"]*mines_multiplier(state["mines"], len(state["opened"]), state["edge"]))
            if path.endswith("cashout") or len(state["opened"]) == 25-state["mines"] or amount >= state["maxPayout"]:
                state["reward"] = self.award(user, amount, state["asPet"], state["maxPayout"])
                self.save_game(game, "won", state["reward"]["payout"])
            else:
                self.save_game(game, "active")
            return self.public_game(game), cookie
        if path == "/api/rocket/start":
            previous = self.settle_rocket(user, self.active_game(user, "rocket"))
            require(not previous or previous["status"] != "active", "Ракета уже летит")
            stake = self.charge_stake(user, body)
            try:
                auto = float(body.get("auto") or 0)
            except (ValueError, TypeError):
                raise APIError("Неверный множитель") from None
            require(math.isfinite(auto) and (auto == 0 or 1.1 <= auto <= 1000), "Автозабор от 1.1x до 1000x")
            seed = self.seed_for(user, "rocket")
            state = {"seed": seed, "crash": crash_point(self.roll(seed), self.cfg.edge), "startAt": now_ms()+3000,
                     "auto": auto, "edge": self.cfg.edge, "maxPayout": self.cfg.max_payout, "asPet": body.get("asPet") is True}
            game_id = self.insert_game(user, "rocket", stake, 0, state, "active")
            return self.public_game(self.decode_game(self.q("SELECT * FROM games WHERE id=?", game_id))), cookie
        if path == "/api/rocket/state":
            game = self.active_game(user, "rocket")
            if game:
                game = self.settle_rocket(user, game)
            else:
                game = self.decode_game(self.q("SELECT * FROM games WHERE user_id=? AND kind='rocket' ORDER BY created_at DESC LIMIT 1", uid))
            return {"game": self.public_game(game), "serverTime": now_ms()}, cookie
        if path == "/api/rocket/cashout":
            game = self.settle_rocket(user, self.active_game(user, "rocket"))
            require(game and game["status"] == "active", "Полёт уже завершён")
            state = game["state"]
            require(now_ms() >= state["startAt"], "Дождись старта")
            multiplier = self.rocket_multiplier(state)
            state["reward"] = self.award(user, game["stake"]*multiplier, state["asPet"], state["maxPayout"])
            state["finalMultiplier"] = multiplier
            self.save_game(game, "won", state["reward"]["payout"])
            return self.public_game(game), cookie
        if path == "/api/requests/create":
            kind = body.get("kind")
            require(kind in {"deposit", "withdraw"}, "Неверный тип заявки")
            name = str(body.get("robloxName", "")).strip()
            require(re.fullmatch(r"[A-Za-z0-9_]{3,20}", name), "Roblox-ник: 3–20 латинских символов")
            require(self.q("SELECT COUNT(*) AS n FROM requests WHERE user_id=? AND status='pending'", uid)["n"] < 3, "Сначала дождись обработки текущих заявок")
            if kind == "deposit":
                ids = body.get("petIds")
                require(isinstance(ids, list) and 1 <= len(ids) <= 20, "Выбери от 1 до 20 предметов")
                require(all(isinstance(i, str) and i in self.pet_by_id for i in ids), "Неизвестный питомец")
                items = [{"petId": i, "value": self.pet_by_id[i]["value"]} for i in ids]
            else:
                ids = unique_ids(body.get("inventoryIds"))
                owned = [self.q("SELECT * FROM inventory WHERE id=? AND user_id=? AND locked=0", i, uid) for i in ids]
                require(all(owned), "Один из питомцев недоступен")
                for item in owned:
                    self.run("UPDATE inventory SET locked=1 WHERE id=?", item["id"])
                items = [{"inventoryId": i["id"], "petId": i["pet_id"], "value": self.pet_by_id[i["pet_id"]]["value"]} for i in owned]
            amount, request_id = sum(i["value"] for i in items), str(uuid.uuid4())
            self.run("INSERT INTO requests(id,user_id,kind,status,amount,items,roblox_name,created_at) VALUES(?,?,?,?,?,?,?,?)",
                     request_id, uid, kind, "pending", amount, json_text(items), name, now_ms())
            self.notify_request({"id": request_id, "user_id": uid, "kind": kind, "amount": amount, "items": items, "roblox_name": name})
            return {"id": request_id, "amount": amount, "status": "pending"}, cookie
        if path == "/api/requests/cancel":
            request = self.q("SELECT * FROM requests WHERE id=? AND user_id=? AND status='pending'", str(body.get("id", "")), uid)
            require(request, "Заявка уже обработана")
            self.run("UPDATE requests SET status='cancelled',reviewed_at=? WHERE id=?", now_ms(), request["id"])
            if request["kind"] == "withdraw":
                for item in json.loads(request["items"]):
                    self.run("UPDATE inventory SET locked=0 WHERE id=?", item["inventoryId"])
            return {"ok": True}, cookie
        raise APIError("Метод не найден", 404)

    def api(self, path, body, headers):
        with self.store.transaction():
            session = self.session(headers, path.startswith("/api/admin/"))
            key = headers.get("Idempotency-Key")
            owner = session["token_hash"] if session else None
            fingerprint = sha256(f"{path}:{json_text(body)}")
            if key:
                require(8 <= len(key) <= 100, "Неверный ключ запроса")
                if owner:
                    previous = self.q("SELECT * FROM idempotency WHERE owner=? AND key=?", owner, key)
                    if previous:
                        require(previous["fingerprint"] == fingerprint, "Ключ уже использован для другого запроса", 409)
                        return json.loads(previous["response"]), None
            result, cookie = self.route(path, body, headers)
            if key and owner:
                self.run("INSERT INTO idempotency(owner,key,fingerprint,response,created_at) VALUES(?,?,?,?,?)", owner, key, fingerprint, json_text(result), now_ms())
            return result, cookie

    def housekeeping(self):
        cycles = 0
        while not self.stop_event.wait(1):
            try:
                with self.store.transaction():
                    for row in self.all("SELECT * FROM games WHERE kind='rocket' AND status='active'"):
                        user = self.q("SELECT * FROM users WHERE id=?", row["user_id"])
                        self.settle_rocket(user, self.decode_game(row))
                    if cycles % 60 == 0:
                        self.run("DELETE FROM sessions WHERE expires<?", now_ms())
                        self.run("DELETE FROM idempotency WHERE created_at<?", now_ms()-DAY*7)
                        self.run("DELETE FROM telegram_updates WHERE created_at<?", now_ms()-DAY*7)
                if cycles % 60 == 0:
                    with self.rate_lock:
                        self.rates = {k: v for k, v in self.rates.items() if time.monotonic()-v[0] < 60}
                cycles += 1
            except Exception:
                LOG.exception("Housekeeping failed")


class TelegramError(Exception):
    def __init__(self, code, message, retry_after=0):
        super().__init__(message)
        self.code, self.retry_after = code, retry_after


class TelegramAPI:
    def __init__(self, token):
        self.token = token

    def call(self, method, payload=None, timeout=15):
        request = urllib.request.Request(
            f"https://api.telegram.org/bot{self.token}/{method}",
            data=json_text(payload or {}).encode(),
            headers={"Content-Type": "application/json", "User-Agent": "nezzxBET/2.0"}, method="POST")
        try:
            with urllib.request.urlopen(request, timeout=timeout) as response:
                result = json.load(response)
        except urllib.error.HTTPError as error:
            try:
                result = json.loads(error.read())
            except (ValueError, OSError):
                raise TelegramError(error.code, "Telegram HTTP request failed") from None
        except (urllib.error.URLError, TimeoutError, OSError):
            raise TelegramError(0, "Telegram connection failed") from None
        if not result.get("ok"):
            description = str(result.get("description", "Telegram API error")).replace(self.token, "[redacted]")
            raise TelegramError(result.get("error_code", 0), description, result.get("parameters", {}).get("retry_after", 0))
        return result.get("result")


class BotEngine:
    def __init__(self, app):
        self.app, self.cfg = app, app.cfg
        self.api = TelegramAPI(self.cfg.bot_token)

    def app_keyboard(self, page="cases"):
        rows = []
        if self.cfg.site_url.startswith("https://"):
            rows.append([{"text": "Открыть nezzxBET", "web_app": {"url": self.cfg.site_url+f"/#/{page}"}}])
        rows.append([{"text": "Баланс", "callback_data": "balance"}, {"text": "Инвентарь", "callback_data": "inventory"}])
        rows.append([{"text": "Ежедневный бонус", "callback_data": "bonus"}])
        if self.cfg.support_url.startswith(("https://", "http://")):
            rows.append([{"text": "Поддержка", "url": self.cfg.support_url}])
        return {"inline_keyboard": rows}

    def reply(self, chat_id, text, keyboard=None, dedupe=None):
        payload = {"chat_id": chat_id, "text": text, "parse_mode": "HTML", "link_preview_options": {"is_disabled": True}}
        if keyboard:
            payload["reply_markup"] = keyboard
        self.app.queue("sendMessage", payload, dedupe)

    def ensure_user(self, telegram, referrer=None):
        user = self.app.q("SELECT * FROM users WHERE telegram_id=?", str(telegram["id"]))
        if user:
            return user, None
        return self.app.create_user(telegram.get("first_name", "Игрок"), str(telegram["id"]), referrer)

    def resolve_target(self, value):
        if value.startswith("tg:"):
            result = self.app.q("SELECT id FROM users WHERE telegram_id=?", str(integer(value[3:])))
        else:
            raw = value[5:] if value.startswith("site:") else value
            result = self.app.q("SELECT id FROM users WHERE id=?", integer(raw))
        require(result, "Игрок не найден. Для Telegram ID используй tg:123456789, для ID сайта — site:123.")
        return result["id"]

    def owner(self, telegram_id):
        require(telegram_id in self.cfg.admin_ids, "Команда доступна администратору", 403)

    def request_message(self, chat_id, request_id):
        request = self.app.q("SELECT * FROM requests WHERE id=?", request_id)
        require(request, "Заявка не найдена")
        items = json.loads(request["items"])
        label = "Депозит" if request["kind"] == "deposit" else "Вывод"
        text = (f"<b>{label} · {request_id[:8]}</b>\nИгрок #{request['user_id']}\n"
                f"Roblox: <code>{html.escape(request['roblox_name'])}</code>\n"
                f"Сумма: {request['amount']/100:g} монет\nСтатус: {html.escape(request['status'])}\n"
                + ", ".join(html.escape(self.app.pet_by_id[i["petId"]]["name"]) for i in items))
        keyboard = {"inline_keyboard": []}
        if request["status"] == "pending":
            text += "\n\nПодтверждай после фактической передачи предметов."
            keyboard["inline_keyboard"].append([
                {"text": "Передача выполнена", "callback_data": f"review:approved:{request_id}"},
                {"text": "Отклонить", "callback_data": f"review:rejected:{request_id}"}])
        self.reply(chat_id, text, keyboard)

    def handle_action(self, action, args, telegram, chat_id, user, code=None):
        uid = user["id"]
        if action in {"start", "help"}:
            text = ("<b>nezzxBET</b>\nКейсы, питомцы, Mines, Upgrade и Rocket.\n\n"
                    f"Твой ID на сайте: <code>{uid}</code>\nБаланс: <b>{user['balance']/100:g}</b> монет.\n"
                    "Игры и пополнение предметами находятся в приложении.")
            if code:
                text += f"\n\nКод восстановления: <code>{code}</code>\nСохрани его для входа в браузере."
            if not self.cfg.site_url.startswith("https://"):
                text += "\n\nВладелец должен добавить HTTPS-адрес SITE_URL, чтобы появилась кнопка приложения."
            self.reply(chat_id, text, self.app_keyboard())
        elif action in {"balance", "profile", "id"}:
            profile = self.app.profile(user)
            self.reply(chat_id,
                       f"<b>{html.escape(profile['name'])}</b>\nID сайта: <code>{uid}</code>\n"
                       f"Telegram ID: <code>{telegram['id']}</code>\nБаланс: <b>{profile['balance']/100:g}</b> монет\n"
                       f"Питомцев: {len(profile['inventory'])}\nРаундов: {profile['stats']['rounds']}", self.app_keyboard("profile"))
        elif action == "inventory":
            profile = self.app.profile(user)
            lines = [f"<b>Инвентарь · {len(profile['inventory'])} питомцев</b>"]
            for pet in profile["inventory"][:20]:
                lock = " · в заявке" if pet["locked"] else ""
                lines.append(f"{html.escape(pet['name'])} — {pet['value']/100:g}{lock}")
            if not profile["inventory"]:
                lines.append("Пока пусто. Открой кейс или купи питомца в магазине.")
            self.reply(chat_id, "\n".join(lines), self.app_keyboard("inventory"))
        elif action == "bonus":
            result = self.app.daily(user)
            self.reply(chat_id, f"На баланс зачислено <b>{result['amount']/100:g} монет</b>. Следующий бонус — через 24 часа.", self.app_keyboard("bonuses"))
        elif action == "support":
            self.reply(chat_id, "Поддержка: "+html.escape(self.cfg.support_url or "Контакт не настроен"), self.app_keyboard())
        elif action == "admin":
            self.owner(telegram["id"])
            keyboard = {"inline_keyboard": [[{"text": "Статистика", "callback_data": "stats"}, {"text": "Заявки", "callback_data": "requests"}]]}
            if self.cfg.site_url.startswith("https://"):
                keyboard["inline_keyboard"].append([{"text": "Веб-админка", "url": self.cfg.site_url+"/admin"}])
            self.reply(chat_id, "<b>Администрирование nezzxBET</b>\n"
                       "/addbalance site:ID СУММА [причина]\n/addbalance tg:TELEGRAM_ID СУММА [причина]\n"
                       "/requests — заявки на трейды\n/stats — статистика\n\nПароль веб-админки — ADMIN_TOKEN из настроек сервиса.", keyboard)
        elif action in {"addbalance", "credit"}:
            self.owner(telegram["id"])
            require(len(args) >= 2, "Формат: /addbalance site:123 100 [причина]")
            target = self.resolve_target(args[0])
            amount = to_cents(args[1])
            self.app.admin_credit({"userId": target, "amount": str(decimal.Decimal(amount)/100), "note": " ".join(args[2:]) or "Начисление через Telegram"}, f"telegram:{telegram['id']}")
            self.reply(chat_id, f"Игроку <code>#{target}</code> начислено <b>{amount/100:g} монет</b>.")
        elif action == "stats":
            self.owner(telegram["id"])
            stats = self.app.admin_data({})["stats"]
            self.reply(chat_id, f"<b>Статистика nezzxBET</b>\nИгроков: {stats['users']}\n"
                       f"Баланс игроков: {stats['balance']/100:g}\nЗаявок в очереди: {stats['pending']}\n"
                       f"Разница ставок и призов: {stats['gameMargin']/100:g}")
        elif action == "requests":
            self.owner(telegram["id"])
            rows = self.app.all("SELECT id FROM requests WHERE status='pending' ORDER BY created_at LIMIT 10")
            if not rows:
                self.reply(chat_id, "Заявок в очереди нет.")
            for row in rows:
                self.request_message(chat_id, row["id"])
        else:
            self.reply(chat_id, "Открой /start для входа в nezzxBET. Список команд: /help.", self.app_keyboard())

    def handle_callback(self, callback, telegram, user):
        message = callback.get("message", {})
        require(message.get("chat", {}).get("type") == "private", "Открой личный чат с ботом")
        chat_id = message["chat"]["id"]
        data = str(callback.get("data", ""))
        self.app.queue("answerCallbackQuery", {"callback_query_id": callback["id"]})
        if data.startswith("request:"):
            self.owner(telegram["id"])
            self.request_message(chat_id, data.split(":", 1)[1])
        elif data.startswith("review:"):
            self.owner(telegram["id"])
            _, decision, request_id = data.split(":", 2)
            require(decision in {"approved", "rejected"}, "Неверное решение")
            request = self.app.q("SELECT id FROM requests WHERE id=? AND status='pending'", request_id)
            require(request, "Заявка уже обработана")
            text = "Подтвердить фактическую передачу предметов?" if decision == "approved" else "Отклонить заявку и снять резерв предметов?"
            self.reply(chat_id, text, {"inline_keyboard": [[{"text": "Да, подтвердить", "callback_data": f"confirm:{decision}:{request_id}"}, {"text": "Назад", "callback_data": f"request:{request_id}"}]]})
        elif data.startswith("confirm:"):
            self.owner(telegram["id"])
            _, decision, request_id = data.split(":", 2)
            self.app.admin_review({"id": request_id, "decision": decision}, f"telegram:{telegram['id']}")
            self.reply(chat_id, f"Заявка <code>{html.escape(request_id[:8])}</code> обработана.")
        else:
            self.handle_action(data, [], telegram, chat_id, user)

    def process_update(self, update):
        require(isinstance(update, dict), "Неверное обновление Telegram")
        update_id = integer(update.get("update_id"), "Нет update_id")
        with self.app.store.transaction():
            if self.app.q("SELECT update_id FROM telegram_updates WHERE update_id=?", update_id):
                return
            callback = update.get("callback_query")
            message = update.get("message") or (callback or {}).get("message") or {}
            telegram = (callback or message).get("from", {})
            if (message.get("chat", {}).get("type") != "private" or not isinstance(telegram.get("id"), int)
                    or telegram.get("is_bot")):
                self.app.run("INSERT INTO telegram_updates(update_id,created_at) VALUES(?,?)", update_id, now_ms())
                self.app.store.set_meta("poll_offset", max(update_id+1, int(self.app.store.meta("poll_offset", 0))))
                return
            chat_id = message["chat"]["id"]
            self.app.run("INSERT INTO bot_chats(telegram_id,chat_id) VALUES(?,?) ON CONFLICT(telegram_id) DO UPDATE SET chat_id=excluded.chat_id", str(telegram["id"]), chat_id)
            text = str(message.get("text", ""))
            parts = text.split()
            action = parts[0].split("@")[0].lstrip("/").lower() if parts else "start"
            args = parts[1:]
            referrer = args[0][2:] if action == "start" and args and args[0].startswith("r_") else None
            user, code = self.ensure_user(telegram, referrer)
            self.app.run("SAVEPOINT bot_command")
            try:
                if callback:
                    self.handle_callback(callback, telegram, user)
                else:
                    self.handle_action(action, args, telegram, chat_id, user, code)
                self.app.run("RELEASE bot_command")
            except (APIError, ValueError, KeyError) as error:
                self.app.run("ROLLBACK TO bot_command")
                self.app.run("RELEASE bot_command")
                safe_message = str(error) if isinstance(error, APIError) else "Не удалось обработать команду. Открой /help."
                if callback:
                    self.app.queue("answerCallbackQuery", {"callback_query_id": callback["id"], "text": safe_message[:180], "show_alert": True})
                else:
                    self.reply(chat_id, html.escape(safe_message))
            self.app.run("INSERT INTO telegram_updates(update_id,created_at) VALUES(?,?)", update_id, now_ms())
            self.app.store.set_meta("poll_offset", max(update_id+1, int(self.app.store.meta("poll_offset", 0))))

    def initialize(self):
        identity = self.api.call("getMe")
        with self.app.store.transaction():
            self.app.store.set_meta("bot_username", identity.get("username", ""))
        commands = [{"command": command, "description": description} for command, description in [
            ("start", "Открыть nezzxBET"), ("balance", "Баланс и ID"), ("inventory", "Мои питомцы"),
            ("bonus", "Ежедневный бонус"), ("support", "Поддержка"), ("help", "Помощь")]]
        self.api.call("setMyCommands", {"commands": commands})
        if self.cfg.site_url.startswith("https://"):
            self.api.call("setChatMenuButton", {"menu_button": {"type": "web_app", "text": "nezzxBET", "web_app": {"url": self.cfg.site_url}}})
        if self.cfg.bot_mode == "webhook":
            if not self.cfg.site_url.startswith("https://"):
                raise TelegramError(400, "Webhook requires an HTTPS SITE_URL")
            self.api.call("setWebhook", {"url": self.cfg.site_url+"/telegram/webhook", "secret_token": self.app.webhook_secret,
                                         "allowed_updates": ["message", "callback_query"], "drop_pending_updates": False})
        else:
            info = self.api.call("getWebhookInfo")
            if info.get("url"):
                if not self.cfg.reset_webhook:
                    raise TelegramError(409, "An existing webhook is active. Use BOT_MODE=webhook, or BOT_RESET_WEBHOOK=true to switch to polling.")
                self.api.call("deleteWebhook", {"drop_pending_updates": False})
        LOG.info("Telegram bot @%s started in %s mode", identity.get("username", ""), self.cfg.bot_mode)

    def run(self):
        while not self.app.stop_event.is_set():
            try:
                self.initialize()
                if self.cfg.bot_mode == "webhook":
                    return
                while not self.app.stop_event.is_set():
                    with self.app.store.lock:
                        offset = int(self.app.store.meta("poll_offset", 0))
                    updates = self.api.call("getUpdates", {"offset": offset, "timeout": 25, "allowed_updates": ["message", "callback_query"]}, timeout=35)
                    for update in updates:
                        if self.app.stop_event.is_set():
                            return
                        self.process_update(update)
            except TelegramError as error:
                LOG.error("Telegram error %s: %s", error.code, str(error))
                if error.code == 409:
                    return
                self.app.stop_event.wait(max(5, min(30, error.retry_after or 10)))
            except Exception:
                LOG.exception("Telegram update processing failed")
                self.app.stop_event.wait(5)

    def dispatch(self):
        chat_times = {}
        while not self.app.stop_event.wait(.08):
            with self.app.store.lock:
                row = self.app.q("SELECT * FROM telegram_outbox WHERE retry_at<=? ORDER BY id LIMIT 1", now_ms())
            if not row:
                self.app.stop_event.wait(.25)
                continue
            payload = json.loads(row["payload"])
            chat = payload.get("chat_id")
            if chat is not None and time.monotonic()-chat_times.get(chat, -10) < 1.05:
                with self.app.store.transaction():
                    self.app.run("UPDATE telegram_outbox SET retry_at=? WHERE id=?", now_ms()+1000, row["id"])
                continue
            try:
                self.api.call(row["method"], payload)
                with self.app.store.transaction():
                    self.app.run("DELETE FROM telegram_outbox WHERE id=?", row["id"])
                if chat is not None:
                    chat_times[chat] = time.monotonic()
            except TelegramError as error:
                attempts = row["attempts"]+1
                with self.app.store.transaction():
                    if error.code in {400, 403, 404} or attempts >= 10:
                        self.app.run("DELETE FROM telegram_outbox WHERE id=?", row["id"])
                        LOG.warning("Telegram delivery failed with code %s", error.code)
                    else:
                        delay = max(error.retry_after or 0, min(300, 2**attempts))
                        self.app.run("UPDATE telegram_outbox SET attempts=?,retry_at=? WHERE id=?", attempts, now_ms()+delay*1000, row["id"])
            except Exception:
                LOG.exception("Telegram outbox processing failed")
                self.app.stop_event.wait(2)


class HTTPServer(http.server.ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True
    request_queue_size = 64

    def __init__(self, address, app, bot):
        self.app, self.bot = app, bot
        self.slots = threading.BoundedSemaphore(64)
        super().__init__(address, Handler)

    def process_request(self, request, client_address):
        if not self.slots.acquire(blocking=False):
            request.close()
            return
        try:
            super().process_request(request, client_address)
        except BaseException:
            self.slots.release()
            raise

    def process_request_thread(self, request, client_address):
        try:
            request.settimeout(15)
            super().process_request_thread(request, client_address)
        finally:
            self.slots.release()


class Handler(http.server.BaseHTTPRequestHandler):
    server_version = "nezzxBET/2.0"
    sys_version = ""
    protocol_version = "HTTP/1.1"

    def log_message(self, fmt, *args):
        if getattr(self.server, "quiet", False):
            return
        if args and str(args[0]).startswith(("GET /health", "GET /api/rocket/state")):
            return
        LOG.info("HTTP %s %s", self.command, urllib.parse.urlsplit(self.path).path)

    def send_bytes(self, status, data, content_type, cookie=None, cache="no-store", etag=None):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", cache)
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "same-origin")
        self.send_header("Content-Security-Policy", "default-src 'self'; script-src 'self' https://telegram.org; style-src 'self' 'unsafe-inline'; img-src 'self' data:; media-src 'self' blob:; connect-src 'self'; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'self' https://web.telegram.org https://telegram.org")
        if etag:
            self.send_header("ETag", etag)
        if cookie:
            self.send_header("Set-Cookie", cookie)
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(data)

    def send_json(self, status, value, cookie=None):
        self.send_bytes(status, json_text(value).encode(), "application/json; charset=utf-8", cookie)

    def read_json(self, maximum=32768):
        require(not self.headers.get("Transfer-Encoding"), "Chunked-запросы не поддерживаются", 400)
        try:
            length = int(self.headers.get("Content-Length", "0"))
        except ValueError:
            raise APIError("Неверный размер запроса") from None
        require(0 <= length <= maximum, "Запрос слишком большой", 413)
        raw = self.rfile.read(length)
        require(len(raw) == length, "Неполный запрос")
        try:
            value = json.loads(raw or b"{}", parse_constant=lambda v: (_ for _ in ()).throw(ValueError(v)))
        except (ValueError, UnicodeError):
            raise APIError("Некорректный JSON") from None
        require(isinstance(value, dict), "Ожидается JSON-объект")
        return value

    def serve(self):
        app = self.server.app
        path = urllib.parse.unquote(urllib.parse.urlsplit(self.path).path)
        try:
            if path == "/health":
                with app.store.lock:
                    app.q("SELECT 1")
                self.send_json(200, {"ok": True})
                return
            if path == "/telegram/webhook":
                require(self.command == "POST", "Требуется POST", 405)
                require(app.cfg.bot_token and app.cfg.bot_mode == "webhook", "Webhook не включён", 404)
                secret = self.headers.get("X-Telegram-Bot-Api-Secret-Token", "")
                require(hmac.compare_digest(secret, app.webhook_secret), "Неверный секрет webhook", 403)
                self.server.bot.process_update(self.read_json(262144))
                self.send_json(200, {"ok": True})
                return
            if path.startswith("/api/"):
                expected_method = "GET" if path in READ_PATHS else "POST"
                require(self.command == expected_method, "Метод запроса не поддерживается", 405)
                peer = self.client_address[0]
                if os.getenv("RENDER"):
                    peer = self.headers.get("X-Forwarded-For", peer).split(",")[0].strip()
                app.rate_limit(peer, "/auth/" in path or path == "/api/admin/login")
                if self.command == "POST":
                    require(self.headers.get("X-Nezzx-Request") == "1", "Недопустимый запрос", 403)
                    origin = self.headers.get("Origin")
                    if origin:
                        expected = app.cfg.site_url or f"{'https' if app.cfg.production else 'http'}://{self.headers.get('Host', '')}"
                        require(origin == expected, "Недопустимый источник", 403)
                    body = self.read_json()
                else:
                    body = {}
                result, cookie = app.api(path, body, self.headers)
                self.send_json(200, result, cookie)
                return
            require(self.command in {"GET", "HEAD"}, "Метод запроса не поддерживается", 405)
            asset_path = "/index.html" if path in {"/", "/admin", "/admin/"} else path
            asset = load_bundle()["assets"].get(asset_path)
            require(asset, "Файл не найден", 404)
            self.send_bytes(200, asset["bytes"], asset["mime"], cache="no-cache" if asset_path.endswith(".html") else "public, max-age=3600")
        except APIError as error:
            self.close_connection = True
            self.send_json(error.status, {"error": str(error)})
        except (BrokenPipeError, ConnectionResetError, TimeoutError):
            self.close_connection = True
        except Exception:
            LOG.exception("HTTP request failed")
            self.close_connection = True
            self.send_json(500, {"error": "Ошибка сервера. Попробуй снова."})

    do_GET = serve
    do_HEAD = serve
    do_POST = serve


def verify_round(round_data):
    proof = round_data.get("proof") or round_data.get("seed") or round_data
    require(sha256(proof["serverSeed"]) == proof["serverSeedHash"], "Server seed hash mismatch")
    value = uniform(proof["serverSeed"], proof["clientSeed"], proof["nonce"], proof["context"])
    result = {"commitValid": True, "context": proof["context"], "nonce": proof["nonce"], "roll": value}
    if "roll" in round_data:
        require(value == round_data["roll"], "Roll mismatch")
    if proof["context"] == "mines" and "mines" in round_data:
        result["bombs"] = mine_positions(proof["serverSeed"], proof["clientSeed"], proof["nonce"], round_data["mines"])
        if "bombs" in round_data:
            require(result["bombs"] == round_data["bombs"], "Mine positions mismatch")
    elif proof["context"] == "upgrade" and "chance" in round_data:
        result["won"] = value < round_data["chance"]
        if "won" in round_data:
            require(result["won"] == round_data["won"], "Upgrade outcome mismatch")
    elif proof["context"] == "rocket" and "edge" in round_data:
        result["crash"] = crash_point(value, round_data["edge"])
        if "crash" in round_data:
            require(result["crash"] == round_data["crash"], "Crash point mismatch")
    elif proof["context"].startswith("case:"):
        drops = round_data.get("odds")
        require(isinstance(drops, list) and drops, "Missing historical case probabilities")
        result["petId"] = pick_drop(drops, value)
        if "item" in round_data:
            require(result["petId"] == round_data["item"]["id"], "Case item mismatch")
    return result


def run_self_tests():
    import concurrent.futures
    import tempfile
    import unittest

    class Checks(unittest.TestCase):
        def setUp(self):
            self.directory = tempfile.TemporaryDirectory(prefix="nezzxbet-python-test-")
            self.config = Config(Path(self.directory.name), "test-admin-password-123456789012345", port=0,
                                 bot_token="test-only-token-no-network", admin_ids=frozenset({900001}),
                                 site_url="https://nezzxbet.example", bot_mode="webhook")
            self.app = Application(self.config)
            self.bot = BotEngine(self.app)
            with self.app.store.transaction():
                self.alice, self.recovery = self.app.create_user("Tester")
                self.app.store.balance(self.alice["id"], 100_000, "Test funding")
                self.cookie = self.app.issue_session(self.alice["id"]).split(";", 1)[0]
                self.admin_cookie = self.app.issue_session(None, True).split(";", 1)[0]

        def tearDown(self):
            self.app.store.close()
            self.directory.cleanup()

        def call(self, path, body=None, admin=False, key=None):
            headers = {"Cookie": self.admin_cookie if admin else self.cookie}
            if key:
                headers["Idempotency-Key"] = key
            return self.app.api(path, body or {}, headers)[0]

        def balance(self):
            return self.call("/api/me")["user"]["balance"]

        def update(self, update_id, text, telegram_id=900001):
            return {"update_id": update_id, "message": {"message_id": update_id,
                    "from": {"id": telegram_id, "first_name": "Bot Tester", "is_bot": False},
                    "chat": {"id": telegram_id, "type": "private"}, "text": text}}

        @contextlib.contextmanager
        def http_server(self):
            server = HTTPServer(("127.0.0.1", 0), self.app, self.bot)
            server.quiet = True
            worker = threading.Thread(target=server.serve_forever, daemon=True)
            worker.start()
            try:
                yield f"http://127.0.0.1:{server.server_address[1]}"
            finally:
                server.shutdown()
                server.server_close()
                worker.join(2)

        def test_01_embedded_assets(self):
            bundle = load_bundle()
            self.assertEqual(len(self.app.cases), 7)
            self.assertEqual(len(self.app.pets), 21)
            for item in self.app.cases+self.app.pets:
                self.assertGreater(len(bundle["assets"][item["image"]]["bytes"]), 100)
            for path in ["/index.html", "/styles.css", "/app.js", "/ui.js", "/assets/hat.svg"]:
                self.assertTrue(bundle["assets"][path]["bytes"])
            self.assertNotIn(b"scripts/verify.mjs", bundle["assets"]["/app.js"]["bytes"])

        def test_02_every_case_rtp(self):
            for edge in [100, 600, 1200, 2000]:
                for definition in load_bundle()["catalog"]["cases"]:
                    pets = [self.app.pet_by_id[i] for i in definition["petIds"]]
                    drops = calibrate_drops(pets, definition["price"], edge)
                    self.assertAlmostEqual(sum(d["chance"] for d in drops), 1, places=12)
                    expectation = sum(self.app.pet_by_id[d["petId"]]["value"]*d["chance"] for d in drops)
                    self.assertAlmostEqual(expectation/definition["price"], 1-edge/10000, places=11)

        def test_03_hmac_mines_and_crash(self):
            expected = int(hmac.new(b"test-server-seed", b"client:17:upgrade:0", hashlib.sha256).hexdigest()[:13], 16)/2**52
            self.assertEqual(uniform("test-server-seed", "client", 17, "upgrade"), expected)
            for count in range(1, 25):
                bombs = mine_positions("seed", "client", 2, count)
                self.assertEqual(len(set(bombs)), count)
                self.assertTrue(all(0 <= x < 25 for x in bombs))
                probability = 1.0
                for opened in range(1, 26-count):
                    probability *= (26-count-opened)/(26-opened)
                    self.assertAlmostEqual(probability*mines_multiplier(count, opened, 600), .94)
            self.assertEqual(crash_point(0, 600), 1)
            self.assertEqual(crash_point(.5, 600), 1.88)
            self.assertEqual(crash_point(.999999999, 600), 1000)

        def test_04_private_boundaries(self):
            with self.assertRaises(APIError):
                self.app.api("/api/me", {}, {})
            with self.assertRaises(APIError):
                self.call("/api/admin/data")
            with self.assertRaises(APIError):
                self.app.api("/api/admin/login", {"token": "wrong"}, {})
            public, _ = self.app.api("/api/config", {}, {})
            self.assertNotIn(self.config.admin_token, json_text(public))
            self.assertNotIn(self.config.bot_token, json_text(public))
            profile = self.call("/api/me")["user"]
            self.assertNotIn("next_seed", profile)
            self.assertNotIn("recovery_hash", profile)

        def test_05_atomic_admin_credit(self):
            def credit(_):
                return self.call("/api/admin/credit", {"userId": self.alice["id"], "amount": 25}, admin=True, key="test-shared-credit")
            with concurrent.futures.ThreadPoolExecutor(max_workers=8) as pool:
                results = list(pool.map(credit, range(8)))
            self.assertTrue(all(r["ok"] for r in results))
            self.assertEqual(self.balance(), 102_500)
            with self.assertRaises(APIError):
                self.call("/api/admin/credit", {"userId": self.alice["id"], "amount": 26}, admin=True, key="test-shared-credit")
            with self.assertRaises(APIError):
                self.call("/api/admin/credit", {"userId": self.alice["id"], "amount": -10}, admin=True)

        def test_06_money_validation(self):
            self.assertEqual(to_cents("1.235"), 124)
            for value in [True, None, "NaN", "Infinity", "-1", "1000001", [], {}]:
                with self.assertRaises(APIError):
                    to_cents(value)
            with self.assertRaises(APIError):
                self.call("/api/shop/buy", {"petId": "__proto__"})

        def test_07_daily_bonus_once(self):
            self.call("/api/bonus/daily")
            self.assertEqual(self.balance(), 100_500)
            with self.assertRaises(APIError):
                self.call("/api/bonus/daily")

        def test_08_buy_sell_garama(self):
            result = self.call("/api/shop/buy", {"petId": "garama"})
            self.assertEqual(self.balance(), 95_500)
            item_id = result["item"]["inventoryId"]
            self.call("/api/inventory/sell", {"inventoryId": item_id})
            self.assertEqual(self.balance(), 100_000)
            with self.assertRaises(APIError):
                self.call("/api/inventory/sell", {"inventoryId": item_id})

        def test_09_case_commit_and_replay(self):
            before = self.call("/api/me")["user"]["fairness"]["nextCommit"]
            receipt = self.call("/api/cases/open", {"caseId": "blocks"}, key="case-request-unique")
            self.assertEqual(receipt["proof"]["serverSeedHash"], before)
            self.assertEqual(sha256(receipt["proof"]["serverSeed"]), before)
            self.assertEqual(verify_round(receipt)["petId"], receipt["item"]["id"])
            second = self.call("/api/cases/open", {"caseId": "blocks"}, key="case-request-unique")
            self.assertEqual(receipt["id"], second["id"])
            self.assertEqual(self.balance(), 99_500)

        def test_10_free_case_limit(self):
            self.call("/api/cases/open", {"caseId": "blocks", "free": True})
            self.assertEqual(self.balance(), 100_000)
            with self.assertRaises(APIError):
                self.call("/api/cases/open", {"caseId": "blocks", "free": True})

        def test_11_upgrade_roll_and_rollback(self):
            with self.assertRaises(APIError):
                self.call("/api/upgrade", {"amount": 50, "targetId": "garama"})
            self.assertEqual(self.balance(), 100_000)
            receipt = self.call("/api/upgrade", {"amount": 1, "targetId": "garama"})
            self.assertEqual(verify_round(receipt)["won"], receipt["won"])

        def test_12_mines_cashout(self):
            game = self.call("/api/mines/start", {"amount": 5, "mines": 3})
            self.assertNotIn("seed", game)
            self.assertNotIn("bombs", game)
            secret = json.loads(self.app.q("SELECT state FROM games WHERE id=?", game["id"])["state"])
            safe = next(i for i in range(25) if i not in secret["bombs"])
            with self.assertRaises(APIError):
                self.call("/api/mines/start", {"amount": 5, "mines": 3})
            self.call("/api/mines/reveal", {"index": safe})
            with self.assertRaises(APIError):
                self.call("/api/mines/reveal", {"index": safe})
            receipt = self.call("/api/mines/cashout")
            self.assertEqual(receipt["status"], "won")
            self.assertEqual(verify_round(receipt)["bombs"], secret["bombs"])
            with self.assertRaises(APIError):
                self.call("/api/mines/cashout")

        def test_13_mines_loss(self):
            game = self.call("/api/mines/start", {"amount": 5, "mines": 24})
            secret = json.loads(self.app.q("SELECT state FROM games WHERE id=?", game["id"])["state"])
            receipt = self.call("/api/mines/reveal", {"index": secret["bombs"][0]})
            self.assertEqual(receipt["status"], "lost")
            self.assertEqual(receipt["payout"], 0)
            self.assertEqual(self.balance(), 99_500)

        def test_14_deposit_and_referrals(self):
            with self.app.store.transaction():
                friend, _ = self.app.create_user("Friend", referrer=self.alice["id"])
                cookie = self.app.issue_session(friend["id"]).split(";", 1)[0]
            request, _ = self.app.api("/api/requests/create", {"kind": "deposit", "petIds": ["garama"], "robloxName": "TestPlayer"}, {"Cookie": cookie})
            self.call("/api/admin/review", {"id": request["id"], "decision": "approved"}, admin=True)
            with self.assertRaises(APIError):
                self.call("/api/admin/review", {"id": request["id"], "decision": "approved"}, admin=True)
            self.assertEqual(self.app.q("SELECT balance FROM users WHERE id=?", friend["id"])["balance"], 4500)
            self.assertEqual(self.call("/api/me")["user"]["referralBalance"], 135)
            self.call("/api/referral/transfer")
            self.assertEqual(self.balance(), 100_135)

        def test_15_withdrawal_reserve_and_cancel(self):
            item = self.call("/api/shop/buy", {"petId": "garama"})["item"]
            request = self.call("/api/requests/create", {"kind": "withdraw", "inventoryIds": [item["inventoryId"]], "robloxName": "TestPlayer"})
            with self.assertRaises(APIError):
                self.call("/api/inventory/sell", {"inventoryId": item["inventoryId"]})
            self.call("/api/requests/cancel", {"id": request["id"]})
            self.call("/api/inventory/sell", {"inventoryId": item["inventoryId"]})
            self.assertEqual(self.balance(), 100_000)

        def test_16_rocket_auto(self):
            with self.app.store.transaction():
                user = self.app.q("SELECT * FROM users WHERE id=?", self.alice["id"])
                seed = secrets.token_hex(32)
                while uniform(seed, user["client_seed"], user["nonce"], "rocket") < .25:
                    seed = secrets.token_hex(32)
                self.app.run("UPDATE users SET next_seed=? WHERE id=?", seed, user["id"])
            game = self.call("/api/rocket/start", {"amount": 5, "auto": 1.1})
            self.assertNotIn("crash", game)
            self.assertNotIn("seed", game)
            with self.assertRaises(APIError):
                self.call("/api/rocket/cashout")
            with self.app.store.transaction():
                state = json.loads(self.app.q("SELECT state FROM games WHERE id=?", game["id"])["state"])
                state["startAt"] = now_ms()-5000
                self.app.run("UPDATE games SET state=? WHERE id=?", json_text(state), game["id"])
            receipt = self.call("/api/rocket/state")["game"]
            self.assertEqual(receipt["status"], "won")
            self.assertEqual(receipt["payout"], 550)
            self.assertEqual(verify_round(receipt)["crash"], state["crash"])
            with self.assertRaises(APIError):
                self.call("/api/rocket/cashout")

        def test_17_telegram_signature(self):
            fields = {"auth_date": str(int(time.time())), "query_id": "test-query", "user": json_text({"id": 700001, "first_name": "Telegram Player"})}
            check = "\n".join(f"{k}={v}" for k, v in sorted(fields.items()))
            secret = hmac.new(b"WebAppData", self.config.bot_token.encode(), hashlib.sha256).digest()
            fields["hash"] = hmac.new(secret, check.encode(), hashlib.sha256).hexdigest()
            signed = urllib.parse.urlencode(fields)
            response, _ = self.app.api("/api/auth/telegram", {"initData": signed}, {})
            self.assertTrue(response["user"]["telegram"])
            with self.assertRaises(APIError):
                self.app.api("/api/auth/telegram", {"initData": signed+"tampered"}, {})

        def test_18_telegram_owner_command_once(self):
            self.bot.process_update(self.update(100, f"/addbalance site:{self.alice['id']} 42 testing"))
            self.bot.process_update(self.update(100, f"/addbalance site:{self.alice['id']} 42 testing"))
            self.assertEqual(self.balance(), 104_200)
            self.bot.process_update(self.update(101, f"/addbalance site:{self.alice['id']} 100", telegram_id=900002))
            self.assertEqual(self.balance(), 104_200)
            self.assertEqual(self.app.q("SELECT COUNT(*) AS n FROM admin_audit WHERE action='credit'")["n"], 1)

        def test_19_telegram_player_commands(self):
            for index, command in enumerate(["/start", "/balance", "/profile", "/id", "/inventory", "/bonus", "/support", "/help"]):
                self.bot.process_update(self.update(200+index, command, telegram_id=700002))
            user = self.app.q("SELECT * FROM users WHERE telegram_id='700002'")
            self.assertEqual(user["balance"], 500)
            queued = self.app.all("SELECT payload FROM telegram_outbox WHERE method='sendMessage'")
            self.assertEqual(len(queued), 8)
            self.assertIn("web_app", json_text(queued))

        def test_20_webhook_and_static_http(self):
            with self.http_server() as origin:
                for path in ["/", "/admin", "/health", "/api/config", "/assets/case-shadow-hat.webp", "/app.js"]:
                    with urllib.request.urlopen(origin+path, timeout=5) as response:
                        self.assertEqual(response.status, 200)
                        self.assertTrue(response.read())
                for path in ["/.env", "/bot.py"]:
                    with self.assertRaises(urllib.error.HTTPError) as error:
                        urllib.request.urlopen(origin+path, timeout=5)
                    self.assertEqual(error.exception.code, 404)
                payload = json_text(self.update(500, "/start", telegram_id=777001)).encode()
                request = urllib.request.Request(origin+"/telegram/webhook", data=payload, headers={"Content-Type": "application/json", "X-Telegram-Bot-Api-Secret-Token": self.app.webhook_secret})
                with urllib.request.urlopen(request, timeout=5) as response:
                    self.assertTrue(json.load(response)["ok"])
                request = urllib.request.Request(origin+"/telegram/webhook", data=payload)
                with self.assertRaises(urllib.error.HTTPError) as error:
                    urllib.request.urlopen(request, timeout=5)
                self.assertEqual(error.exception.code, 403)

        def test_21_backup_recovery_and_restart(self):
            item = self.call("/api/shop/buy", {"petId": "garama"})["item"]
            balance = self.balance()
            path = self.app.store.backup(Path(self.directory.name)/"copy.sqlite")
            with sqlite3.connect(path) as db:
                self.assertEqual(db.execute("SELECT balance FROM users WHERE id=?", (self.alice["id"],)).fetchone()[0], balance)
            other = Application(self.config)
            try:
                profile, _ = other.api("/api/me", {}, {"Cookie": self.cookie})
                self.assertEqual(profile["user"]["balance"], balance)
                self.assertEqual(profile["user"]["inventory"][0]["inventoryId"], item["inventoryId"])
                result, _ = other.api("/api/auth/restore", {"id": self.alice["id"], "recoveryCode": self.recovery}, {})
                self.assertEqual(result["user"]["id"], self.alice["id"])
            finally:
                other.store.close()

    result = unittest.TextTestRunner(verbosity=2).run(unittest.defaultTestLoader.loadTestsFromTestCase(Checks))
    return result.wasSuccessful()


def main():
    parser = argparse.ArgumentParser(description="nezzxBET: self-contained Python site and Telegram bot")
    parser.add_argument("--self-test", action="store_true", help="Run offline tests without Telegram network calls")
    parser.add_argument("--verify", type=Path, metavar="ROUND.json", help="Verify a copied game receipt")
    parser.add_argument("--backup", type=Path, metavar="COPY.sqlite", help="Create a consistent SQLite backup")
    parser.add_argument("--export-static", type=Path, metavar="DIRECTORY", help="Export the embedded interface and images")
    args = parser.parse_args()
    logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s", datefmt="%H:%M:%S")
    if sys.version_info < (3, 11):
        parser.error("Python 3.11 or newer is required")
    if args.self_test:
        raise SystemExit(0 if run_self_tests() else 1)
    if args.verify:
        try:
            result = verify_round(json.loads(args.verify.read_text(encoding="utf-8")))
        except (APIError, ValueError, KeyError, OSError) as error:
            parser.error(str(error))
        print(json.dumps(result, ensure_ascii=False, indent=2))
        return
    if args.export_static:
        root = args.export_static.resolve()
        for path, asset in load_bundle()["assets"].items():
            target = root/path.lstrip("/")
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(asset["bytes"])
        print(f"Exported {len(load_bundle()['assets'])} files to {root}")
        return
    try:
        config = Config.from_env()
        app = Application(config)
    except (ValueError, APIError, OSError) as error:
        parser.error(str(error))
    if args.backup:
        try:
            print(app.store.backup(args.backup))
        finally:
            app.store.close()
        return
    bot = BotEngine(app)
    server = HTTPServer(("0.0.0.0", config.port), app, bot)
    workers = [threading.Thread(target=app.housekeeping, daemon=True, name="maintenance")]
    if config.bot_token:
        workers.extend([threading.Thread(target=bot.run, daemon=True, name="telegram-updates"),
                        threading.Thread(target=bot.dispatch, daemon=True, name="telegram-outbox")])
    else:
        LOG.info("Web app enabled. Add BOT_TOKEN to enable the Telegram bot.")
    for worker in workers:
        worker.start()
    stopped = threading.Event()

    def stop(signum, frame):
        if stopped.is_set():
            return
        stopped.set()
        app.stop_event.set()
        threading.Thread(target=server.shutdown, daemon=True).start()

    for sig in (signal.SIGINT, signal.SIGTERM):
        signal.signal(sig, stop)
    LOG.info("nezzxBET listening on port %s. Admin panel: /admin", server.server_address[1])
    if config.production and config.data_dir.name == "data" and not os.getenv("DATA_DIR"):
        LOG.warning("Set DATA_DIR to an attached persistent disk to preserve data across deployments.")
    try:
        server.serve_forever(poll_interval=.25)
    finally:
        app.stop_event.set()
        server.server_close()
        for worker in workers:
            worker.join(timeout=2)
        app.store.close()


if __name__ == "__main__":
    main()
